-- Schema for a new Neon PostgreSQL database.
-- Mirrors the current EF Core migrations through AddAdminRole.
-- Run once in Neon SQL Editor or with psql against an empty database.

BEGIN;

CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

CREATE TABLE users (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Email" text NOT NULL,
    "Senha" text NOT NULL,
    "DataCadastro" timestamp with time zone NOT NULL,
    "NormalizedEmail" text NOT NULL,
    "NormalizedName" text NOT NULL,
    "PasswordVersion" integer NOT NULL DEFAULT 0,
    "SenhaHashed" boolean NOT NULL DEFAULT false,
    "IsAdmin" boolean NOT NULL DEFAULT false,
    "MustChangePassword" boolean NOT NULL DEFAULT false
);

CREATE TABLE cards (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" character varying(200) NOT NULL,
    "Type" character varying(16) NOT NULL,
    "Attribute" character varying(16),
    "MonsterRace" character varying(32),
    "Level" integer,
    "Attack" integer,
    "Defense" integer,
    "Description" text NOT NULL,
    "ImageUrl" character varying(500),
    "Archetype" character varying(100),
    "Rarity" character varying(50)
);

CREATE TABLE decks (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" integer NOT NULL,
    "Name" character varying(150) NOT NULL,
    "Description" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "FK_decks_users_UserId" FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE CASCADE
);

CREATE TABLE deck_cards (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DeckId" integer NOT NULL,
    "CardId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "Section" character varying(16) NOT NULL,
    CONSTRAINT "CK_deck_cards_Quantity" CHECK ("Quantity" > 0),
    CONSTRAINT "FK_deck_cards_cards_CardId" FOREIGN KEY ("CardId") REFERENCES cards ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_deck_cards_decks_DeckId" FOREIGN KEY ("DeckId") REFERENCES decks ("Id") ON DELETE CASCADE
);

CREATE TABLE user_favorite_cards (
    "UserId" integer NOT NULL,
    "CardId" integer NOT NULL,
    CONSTRAINT "PK_user_favorite_cards" PRIMARY KEY ("UserId", "CardId"),
    CONSTRAINT "FK_user_favorite_cards_users_UserId" FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_user_favorite_cards_cards_CardId" FOREIGN KEY ("CardId") REFERENCES cards ("Id") ON DELETE CASCADE
);

CREATE TABLE password_reset_tokens (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" integer NOT NULL,
    "TokenHash" character varying(64) NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "UsedAt" timestamp with time zone,
    CONSTRAINT "FK_password_reset_tokens_users_UserId" FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_users_NormalizedEmail" ON users ("NormalizedEmail")
    WHERE length("NormalizedEmail") BETWEEN 3 AND 254;
CREATE UNIQUE INDEX "IX_users_NormalizedName" ON users ("NormalizedName")
    WHERE length("NormalizedName") BETWEEN 3 AND 100;
CREATE INDEX "IX_cards_Archetype" ON cards ("Archetype");
CREATE INDEX "IX_cards_Name" ON cards ("Name");
CREATE INDEX "IX_cards_Type" ON cards ("Type");
CREATE INDEX "IX_decks_UserId" ON decks ("UserId");
CREATE INDEX "IX_deck_cards_CardId" ON deck_cards ("CardId");
CREATE UNIQUE INDEX "IX_deck_cards_DeckId_CardId_Section" ON deck_cards ("DeckId", "CardId", "Section");
CREATE INDEX "IX_user_favorite_cards_CardId" ON user_favorite_cards ("CardId");
CREATE UNIQUE INDEX "IX_password_reset_tokens_TokenHash" ON password_reset_tokens ("TokenHash");
CREATE INDEX "IX_password_reset_tokens_UserId_ExpiresAt" ON password_reset_tokens ("UserId", "ExpiresAt");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion") VALUES
    ('20260909191236_InitialCreate', '10.0.12'),
    ('20261021150647_CriarTabelasCards', '10.0.12'),
    ('20261106204211_AddUserFavoriteCards', '10.0.12'),
    ('20261108210325_HardenAuthentication', '10.0.12'),
    ('20261120174307_AddAdminRole', '10.0.12');

COMMIT;
